solid={r for r in range(len(g)) if len(set(g[r]))==1}
out=[]
for r,row in enumerate(g):
    if len(set(row))==1:
        out.append(row[:]); continue
    # find nearest solid row color
    best=None
    for d in range(1,len(g)):
        for rr in (r-d,r+d):
            if rr in solid: best=(d,g[rr][0]); break
        if best: break
    keep=best[1]
    out.append([keep if v==keep else (1 if v!=keep else v) for v in row])
